-- Delivery cities within ~100km of Hobart with cached courier quote data.
--
-- Seed sourced from refs/tasmania-cities-within-100km.json
-- (quote_data stores shippingQuotes with errors/error fields omitted).

create table public.delivery_cities (
  id bigint generated by default as identity primary key,
  name text not null,
  postal_code integer not null,
  my_distance numeric,
  quote_data jsonb,
  created_at timestamptz not null default now(),
  constraint delivery_cities_name_length check (
    char_length(trim(name)) between 1 and 256
  ),
  constraint delivery_cities_postal_code_range check (
    postal_code between 1000 and 9999
  )
);

comment on table public.delivery_cities is
  'Tasmania delivery suburbs within ~100km of Hobart with cached courier quotes.';
comment on column public.delivery_cities.postal_code is
  'Australian 4-digit postcode.';
comment on column public.delivery_cities.my_distance is
  'Road distance in km from Hobart (7000).';
comment on column public.delivery_cities.quote_data is
  'Cached shippingQuotes payload (errors and error fields excluded).';

create index delivery_cities_postal_code_idx
  on public.delivery_cities (postal_code);

create index delivery_cities_name_idx
  on public.delivery_cities (name);

alter table public.delivery_cities enable row level security;

create policy "Anyone can read delivery cities"
  on public.delivery_cities
  for select
  to anon, authenticated
  using (true);

grant select on public.delivery_cities to anon, authenticated;
grant all on public.delivery_cities to service_role;

grant insert, update, delete on public.delivery_cities to authenticated;

create policy "Admins can insert delivery cities"
  on public.delivery_cities
  for insert
  to authenticated
  with check (public.is_admin());

create policy "Admins can update delivery cities"
  on public.delivery_cities
  for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy "Admins can delete delivery cities"
  on public.delivery_cities
  for delete
  to authenticated
  using (public.is_admin());

create policy "Admins can read all delivery cities"
  on public.delivery_cities
  for select
  to authenticated
  using (public.is_admin());

